import 'package:bloc/bloc.dart';import '../../../../../../../Core/Storage/Local/local_storage_service.dart';import '../../../../../../../Core/Storage/Local/local_storage_keys.dart';import '../../../domain/useCases/cart_use_case.dart';import 'cart_state.dart';class CartCubit extends Cubit<CartStates> {  CartCubit(this.getCartUseCase) : super(CartStates());  final GetCartUseCase getCartUseCase;  init() {    final String token =        LocalStorageService.getValue(LocalStorageKeys.token, defaultValue: "");    if (token.isNotEmpty) {      emit(state.copyWith(loading: true));      getCartItems();      emit(state.copyWith(loading: false));    }  }  void getCartItems() async {    final result = await getCartUseCase.call();    result.fold(      (l) {        emit(        state.copyWith(error: l.errMessage,success: false),      );      },      (r) {        emit(          state.copyWith(cartItems: r,success: true),        );      },    );  }}